<!doctype html>
<html lang="ar" dir="rtl">
<head>
    <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
    <title>{{ $title ?? 'مدرسة طموح الإلكترونية' }}</title>
    <link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800&display=swap" rel="stylesheet">
    <style>
      :root{--ink:#241432;--plum:#291541;--coral:#f4674a;--mint:#1d9b69;--sun:#ffc857;--paper:#fffdfa;--soft:#fff4ec;--muted:#756882;--line:#eadfeb}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:Cairo,Arial,sans-serif;line-height:1.7}a{text-decoration:none;color:inherit}.container{width:min(1140px,calc(100% - 36px));margin:auto}.topbar{position:sticky;top:0;z-index:20;background:#fffdfaf2;backdrop-filter:blur(12px);border-bottom:1px solid var(--line)}.nav{min-height:74px;display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{display:flex;align-items:center;gap:10px;font-weight:800;color:var(--plum)}.brand-mark{width:42px;height:42px;display:grid;place-items:center;border-radius:14px 14px 5px 14px;background:var(--coral);color:#fff;font-size:21px}.brand small{display:block;color:var(--muted);font-size:10px;font-weight:400;margin-top:-5px}.links{display:flex;gap:22px;color:#594b64;font-size:13px;font-weight:700}.links a:hover,.links a.active{color:var(--coral)}.actions{display:flex;gap:8px;align-items:center}.button{display:inline-block;border:0;border-radius:99px;padding:11px 19px;background:var(--coral);color:#fff;font:700 13px Cairo;cursor:pointer}.ghost{background:transparent;color:var(--ink)}.hero{position:relative;overflow:hidden;padding:100px 0 130px;background:linear-gradient(105deg,#21133d,#4b2c75 65%,#2b1749);color:#fff}.hero:after{content:'';position:absolute;inset:auto -10% -150px;height:240px;background:#fff;border-radius:50% 50% 0 0/55% 55% 0 0}.hero-content{position:relative;z-index:1;max-width:700px;text-align:center;margin:auto}.badge,.eyebrow{display:inline-block;padding:5px 13px;border-radius:99px;background:#ffffff18;border:1px solid #ffffff26;color:#ffe4a4;font-size:11px;font-weight:800}.hero h1{font-size:52px;line-height:1.35;margin:18px 0}.hero h1 span,.section-head span{color:var(--sun)}.hero p{color:#e4d8ef;font-size:15px;max-width:600px;margin:auto}.hero-actions{display:flex;justify-content:center;gap:12px;margin-top:28px}.outline{border:1px solid #ffffff66;border-radius:99px;padding:10px 19px;font-size:13px;font-weight:700}.stats{position:relative;z-index:2;margin-top:-56px;background:#fff;border:1px solid var(--line);border-radius:20px;padding:22px;display:grid;grid-template-columns:repeat(4,1fr);box-shadow:0 20px 45px #2616471f}.stat{text-align:center;border-left:1px solid var(--line)}.stat:last-child{border:0}.stat strong{display:block;font-size:22px;color:#59369b}.stat span,.muted{font-size:12px;color:var(--muted)}section{padding:82px 0}.section-head{text-align:center;max-width:650px;margin:0 auto 34px}.eyebrow{background:#ffeadf;border:0;color:#c7462d}.section-head h2{font-size:31px;line-height:1.4;margin:12px 0}.section-head p{font-size:13px;color:var(--muted)}.steps,.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.steps{grid-template-columns:repeat(4,1fr)}.card,.panel{background:#fff;border:1px solid var(--line);border-radius:18px;padding:21px}.card h3{margin:10px 0 4px}.card p{font-size:12px;color:var(--muted)}.number{width:48px;height:48px;display:grid;place-items:center;border-radius:50%;background:var(--coral);color:#fff;font-weight:800;font-size:18px}.subjects{background:var(--soft)}.icon{width:48px;height:48px;display:grid;place-items:center;border-radius:15px 15px 15px 4px;background:var(--coral);color:#fff;font-size:20px;font-weight:800}.cta{background:var(--plum);color:#fff;border-radius:24px;padding:34px;display:flex;align-items:center;justify-content:space-between}.cta p{color:#d9cbe8}.footer{border-top:1px solid var(--line);padding:28px 0;color:var(--muted);font-size:12px;display:flex;justify-content:space-between;gap:15px}.price{font-size:24px;color:var(--coral);font-weight:800}.card a{color:var(--coral);font-size:12px;font-weight:800}@media(max-width:760px){.links{display:none}.actions{display:none}.hero{padding:68px 0 120px}.hero h1{font-size:35px}.stats,.steps,.grid{grid-template-columns:1fr 1fr}.stat:nth-child(2){border:0}.cta,.footer{display:block}.cta .button{margin-top:18px}.section-head h2{font-size:26px}}@media(max-width:480px){.stats,.steps,.grid{grid-template-columns:1fr}.stat{border:0;border-bottom:1px solid var(--line);padding:9px}.stat:last-child{border:0}}
    </style>
</head>
